// Project structure with Gradle Wrapper
// myproject/
//   ├── gradlew           (Unix/Mac script)
//   ├── gradlew.bat       (Windows script)
//   ├── gradle/
//   │   └── wrapper/
//   │       ├── gradle-wrapper.jar
//   │       └── gradle-wrapper.properties  // Specifies Gradle version
//   ├── build.gradle
//   └── settings.gradle

// gradle-wrapper.properties content:
distributionBase=GRADLE_USER_HOME
distributionPath=wrapper/dists
distributionUrl=https\://services.gradle.org/distributions/gradle-8.5-bin.zip
zipStoreBase=GRADLE_USER_HOME
zipStorePath=wrapper/dists

// Running builds with the wrapper:
// Unix/Mac:
./gradlew clean build

// Windows:
gradlew.bat clean build

// The wrapper downloads Gradle 8.5 to ~/.gradle/wrapper/dists/ on first run
// Subsequent runs use the cached version instantly

// settings.gradle — enable build cache for the project
buildCache {
    local {
        enabled = true
        directory = new File(rootDir, 'build-cache')
        removeUnusedEntriesAfterDays = 30
    }

    remote(HttpBuildCache) {
        url = 'https://cache.example.com/cache/'  // Shared team cache
        push = true  // Allow pushing outputs to remote cache
        credentials {
            username = System.getenv('CACHE_USERNAME')
            password = System.getenv('CACHE_PASSWORD')
        }
    }
}

// Running a build with cache:
// First run: tasks execute normally, outputs stored in cache
./gradlew build --build-cache

// Second run: cache hits, tasks show FROM-CACHE instead of UP-TO-DATE
./gradlew clean build --build-cache
// Output: :compileJava FROM-CACHE (retrieved from cache in 0.2s)

plugins {
    id 'java'
    id 'org.springframework.boot' version '3.2.0'
    id 'io.spring.dependency-management' version '1.1.4'
}

group = 'com.example'
version = '1.0.0'

java {
    sourceCompatibility = '17'  // Java version for compilation
}

repositories {
    mavenCentral()  // Download dependencies from Maven Central
}

dependencies {
    // Spring Boot starters — versions managed by spring-boot plugin
    implementation 'org.springframework.boot:spring-boot-starter-web'
    implementation 'org.springframework.boot:spring-boot-starter-data-jpa'

    runtimeOnly 'com.h2database:h2'  // Database driver at runtime only

    testImplementation 'org.springframework.boot:spring-boot-starter-test'
}

tasks.named('test') {
    useJUnitPlatform()  // Enable JUnit 5
}
